mapper.select:
select t.id as applyId, t.device_id as deviceId, t.apply_type as applyType, t.apply_status as applyStatus, t.apply_time as applyTime, t.apply_person as applyPerson, t.approve_person as approvePerson, t.approve_reason as approveReason, t.created_time as createdTime, t.updated_time as updatedTime, td.device_no as deviceNo, td.device_name as deviceName from t_device_apply t inner join t_device td on t.device_id = td.id
t.del_flag = 'N'
and t.apply_type = #{queryDTO.applyType}
and t.apply_status = #{queryDTO.applyStatus}
and t.apply_time >= #{queryDTO.applyTimeBegin}
and t.apply_time <= #{queryDTO.applyTimeEnd}
and t.apply_person = #{queryDTO.applyPerson}
and t.apply_person_acct = #{queryDTO.applyPersonAcct}
order by t.created_time desc
